-- Refreshes the InsureMart partner row's publicMetadata.policies with the
-- real student travel/medical insurance plans, re-sourced directly from the
-- four underlying insurers' own brochures supplied by the business owner
-- (Jubilee "Student Travel Brief", Habib Insurance "Travel Protect" -- with
-- Covid coverage, TPL Insurance "Travel Takaful" brochure Apr 2025, Atlas
-- Insurance "Travel Premium Rates & Coverage" 2026 workbook). Figures kept
-- exactly as published, only rounded to the nearest PKR where the source
-- gave fractional premiums. Filtered to student-specific plans only
-- (domestic, worldwide/Schengen/Diamond and Hajj/Umrah/Ziarat plans from
-- the same brochures were excluded as not relevant to SOUP's student
-- audience). Supersedes migration 20261007090000_insuremart_student_policies:
-- adds 12-month and with-tuition-fee pricing for Jubilee and TPL (previously
-- only the cheapest 6-month, no-tuition figure was captured), and adds
-- Atlas's "Including USA/Canada/Japan/Australia" plan variants and their
-- 12/24-month pricing alongside the existing "Excluding" variants.

UPDATE partners
SET "publicMetadata" = jsonb_set("publicMetadata", '{policies}', '[
    {"name": "Jubilee ViaCare - Student Bronze", "description": "USD 10,000 medical and hospitalization abroad, tuition fee cover up to USD 7,500, repatriation of mortal remains up to USD 5,000, loss of passport up to USD 300, loss of in-flight baggage up to USD 500, 24-hour personal accident cover up to USD 7,500. 6 or 12 month terms.", "price": "PKR 9,799 (6mo, no tuition) · PKR 11,523 (6mo, with tuition) · PKR 15,019 (12mo, no tuition) · PKR 17,666 (12mo, with tuition)"},
